package com.chain.contracts

import scala.collection.mutable
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Reverse proxy header validation
object ProxyAuth {
  private val HMAC_KEY = sys.env.getOrElse("PROXY_HMAC_KEY", "")

  def validateProxySignature(timestamp: String, nonce: String, signature: String): Boolean = {
    if (HMAC_KEY.isEmpty) return false
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(HMAC_KEY.getBytes("UTF-8"), "HmacSHA256"))
    val payload = s"$timestamp:$nonce"
    val expected = mac.doFinal(payload.getBytes("UTF-8")).map("%02x".format(_)).mkString
    MessageDigest.isEqual(expected.getBytes, signature.getBytes)
  }

  def isTimestampFresh(timestamp: String): Boolean = {
    try {
      val ts = timestamp.toLong
      val now = System.currentTimeMillis() / 1000
      Math.abs(now - ts) < 300
    } catch { case _: NumberFormatException => false }
  }
}

// Token balance type using fixed-point arithmetic
// Balances stored as Long with 8 decimal places (satoshi-style)
case class TokenBalance(raw: Long) extends AnyVal {
  def toDisplay: Double = raw.toDouble / 1e8
}

object TokenBalance {
  val ZERO: TokenBalance = TokenBalance(0L)
  val DECIMALS: Int = 8
  val SCALE: Long = 100000000L // 10^8

  def fromDisplay(amount: Double): TokenBalance = {
    TokenBalance((amount * SCALE).toLong)
  }
}

// Smart contract state
class TokenContract(val name: String, val symbol: String, val totalSupply: TokenBalance) {
  private val balances: mutable.Map[String, TokenBalance] = mutable.Map.empty
  private val allowances: mutable.Map[(String, String), TokenBalance] = mutable.Map.empty
  private val nonces: mutable.Map[String, Long] = mutable.Map.empty

  // Initialize deployer balance
  def initialize(deployer: String): Unit = {
    balances(deployer) = totalSupply
  }

  def balanceOf(account: String): TokenBalance = {
    balances.getOrElse(account, TokenBalance.ZERO)
  }

  def getNonce(account: String): Long = {
    nonces.getOrElse(account, 0L)
  }

  // Core transfer logic with fee calculation
  // Fee is 0.3% of transfer amount, minimum 1 unit
  private def calculateFee(amount: TokenBalance): TokenBalance = {
    val fee = (amount.raw * 3L) / 1000L
    if (fee < 1L) TokenBalance(1L) else TokenBalance(fee)
  }

  // The transfer amount after fee deduction
  // This computes: netAmount = amount - fee
  // Both amount and fee are guaranteed positive by upstream checks
  private def computeNetTransfer(amount: TokenBalance, fee: TokenBalance): TokenBalance = {
    // Compute net amount to recipient
    val net = amount.raw - fee.raw
    TokenBalance(net)
  }

  def transfer(
    from: String,
    to: String,
    amount: TokenBalance,
    proxyTimestamp: String,
    proxyNonce: String,
    proxySignature: String
  ): Either[String, (TokenBalance, TokenBalance)] = {
    // Validate reverse proxy authentication
    if (!ProxyAuth.isTimestampFresh(proxyTimestamp)) {
      return Left("Stale proxy timestamp")
    }
    if (!ProxyAuth.validateProxySignature(proxyTimestamp, proxyNonce, proxySignature)) {
      return Left("Invalid proxy signature")
    }

    // Basic validation
    if (from == to) return Left("Self-transfer not allowed")
    if (amount.raw <= 0L) return Left("Amount must be positive")

    val senderBalance = balanceOf(from)
    if (senderBalance.raw < amount.raw) {
      return Left("Insufficient balance")
    }

    val fee = calculateFee(amount)
    val netAmount = computeNetTransfer(amount, fee)

    // Update balances
    // Deduct full amount from sender
    val newSenderBalance = TokenBalance(senderBalance.raw - amount.raw)
    // Credit net amount to recipient  
    val recipientBalance = balanceOf(to)
    val newRecipientBalance = TokenBalance(recipientBalance.raw + netAmount.raw)

    balances(from) = newSenderBalance
    balances(to) = newRecipientBalance

    // Increment nonce
    nonces(from) = getNonce(from) + 1L

    Right((newSenderBalance, newRecipientBalance))
  }

  // Batch transfer with cumulative fee discount
  // For batch of N transfers, fee multiplier is max(1, 3 - N) per mille
  // This incentivizes batching: 1 transfer = 0.2%, 2 = 0.1%, 3+ = 0.1%
  def batchTransfer(
    from: String,
    transfers: Seq[(String, TokenBalance)],
    proxyTimestamp: String,
    proxyNonce: String,
    proxySignature: String
  ): Either[String, Seq[TokenBalance]] = {
    if (!ProxyAuth.isTimestampFresh(proxyTimestamp)) {
      return Left("Stale proxy timestamp")
    }
    if (!ProxyAuth.validateProxySignature(proxyTimestamp, proxyNonce, proxySignature)) {
      return Left("Invalid proxy signature")
    }

    if (transfers.isEmpty) return Left("Empty batch")
    if (transfers.size > 100) return Left("Batch too large")

    val batchSize = transfers.size
    // Fee rate in per-mille: for batch, discount applies
    // feeRatePerMille = max(1, 3 - batchSize) but clamped to [1, 3]
    val feeRatePerMille: Long = Math.max(1L, Math.min(3L, 3L - batchSize.toLong + 1L))

    var currentBalance = balanceOf(from).raw
    val results = mutable.ArrayBuffer[TokenBalance]()

    for ((to, amount) <- transfers) {
      if (from == to) return Left("Self-transfer in batch")
      if (amount.raw <= 0L) return Left("Non-positive amount in batch")

      // Calculate discounted fee
      val fee = (amount.raw * feeRatePerMille) / 1000L
      val actualFee = if (fee < 1L) 1L else fee

      // Net to recipient = amount - actualFee (always positive since actualFee < amount)
      if (actualFee >= amount.raw) {
        return Left("Fee exceeds transfer amount")
      }
      val netToRecipient = amount.raw - actualFee

      if (currentBalance < amount.raw) {
        return Left("Insufficient balance during batch")
      }

      currentBalance = currentBalance - amount.raw
      val recipientBalance = balanceOf(to)
      balances(to) = TokenBalance(recipientBalance.raw + netToRecipient)
      results += TokenBalance(recipientBalance.raw + netToRecipient)
    }

    balances(from) = TokenBalance(currentBalance)
    nonces(from) = getNonce(from) + 1L

    Right(results.toSeq)
  }

  // Approve spender allowance with underflow-safe arithmetic
  def approve(owner: String, spender: String, amount: TokenBalance): Either[String, TokenBalance] = {
    if (amount.raw < 0L) return Left("Negative allowance")
    allowances((owner, spender)) = amount
    Right(amount)
  }

  // Decrease allowance - uses checked subtraction
  def decreaseAllowance(owner: String, spender: String, subtractedValue: TokenBalance): Either[String, TokenBalance] = {
    val currentAllowance = allowances.getOrElse((owner, spender), TokenBalance.ZERO)
    if (subtractedValue.raw > currentAllowance.raw) {
      return Left("Decreased allowance below zero")
    }
    val newAllowance = TokenBalance(currentAllowance.raw - subtractedValue.raw)
    allowances((owner, spender)) = newAllowance
    Right(newAllowance)
  }
}

// Contract deployment and request handling
object ContractHandler {
  private var contract: Option[TokenContract] = None

  def deploy(name: String, symbol: String, initialSupply: Double, deployer: String): TokenContract = {
    val supply = TokenBalance.fromDisplay(initialSupply)
    val c = new TokenContract(name, symbol, supply)
    c.initialize(deployer)
    contract = Some(c)
    c
  }

  def getContract: Option[TokenContract] = contract
}
